#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    scanf("%d", &n);
    vector<int> data(n), deg(n, 0);
    vector<char> removed(n, 0);
    for (auto &x : data) scanf("%d", &x);
    vector<vector<int>> adj(n);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        adj[a].push_back(b);
        adj[b].push_back(a);
        deg[a]++, deg[b]++;
    }
    // Phase 1: repeatedly strip leaves without data.
    deque<int> q;
    for (int i = 0; i < n; i++)
        if (deg[i] <= 1 && data[i] == 0) q.push_back(i);
    while (!q.empty()) {
        int u = q.front();
        q.pop_front();
        if (removed[u]) continue;
        removed[u] = 1;
        for (int v : adj[u])
            if (!removed[v]) {
                deg[v]--, deg[u]--;
                if (deg[v] == 1 && data[v] == 0) q.push_back(v);
            }
    }
    // Phase 2: strip the two outermost leaf layers of what remains.
    q.clear();
    for (int i = 0; i < n; i++)
        if (!removed[i] && deg[i] == 1) q.push_back(i);
    for (int round = 0; round < 2; round++) {
        size_t cnt = q.size();
        for (size_t k = 0; k < cnt; k++) {
            int u = q.front();
            q.pop_front();
            removed[u] = 1;
            for (int v : adj[u])
                if (!removed[v]) {
                    deg[v]--, deg[u]--;
                    if (deg[v] == 1) q.push_back(v);
                }
        }
    }
    long long total = 0;
    for (int i = 0; i < n; i++)
        if (!removed[i]) total += deg[i];
    printf("%lld\n", total);
}

import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        int[] data = new int[n], deg = new int[n];
        boolean[] removed = new boolean[n];
        for (int i = 0; i < n; i++) data[i] = nextInt();
        int[] eu = new int[n - 1], ev = new int[n - 1];
        for (int i = 0; i < n - 1; i++) {
            eu[i] = nextInt();
            ev[i] = nextInt();
            deg[eu[i]]++;
            deg[ev[i]]++;
        }
        // Adjacency in CSR form.
        int[] start = new int[n + 1];
        for (int i = 0; i < n; i++) start[i + 1] = start[i] + deg[i];
        int[] fill = new int[n], adj = new int[2 * (n - 1)];
        for (int i = 0; i < n - 1; i++) {
            adj[start[eu[i]] + fill[eu[i]]++] = ev[i];
            adj[start[ev[i]] + fill[ev[i]]++] = eu[i];
        }
        // Each node enters the queue a bounded number of times; 4n slots are plenty.
        int[] q = new int[4 * n + 4];
        int head = 0, tail = 0;
        // Phase 1: repeatedly strip leaves without data.
        for (int i = 0; i < n; i++)
            if (deg[i] <= 1 && data[i] == 0) q[tail++] = i;
        while (head < tail) {
            int u = q[head++];
            if (removed[u]) continue;
            removed[u] = true;
            for (int k = start[u]; k < start[u + 1]; k++) {
                int v = adj[k];
                if (!removed[v]) {
                    deg[v]--;
                    deg[u]--;
                    if (deg[v] == 1 && data[v] == 0) q[tail++] = v;
                }
            }
        }
        // Phase 2: strip the two outermost leaf layers of what remains.
        head = tail = 0;
        for (int i = 0; i < n; i++)
            if (!removed[i] && deg[i] == 1) q[tail++] = i;
        for (int round = 0; round < 2; round++) {
            int end = tail;
            while (head < end) {
                int u = q[head++];
                removed[u] = true;
                for (int k = start[u]; k < start[u + 1]; k++) {
                    int v = adj[k];
                    if (!removed[v]) {
                        deg[v]--;
                        deg[u]--;
                        if (deg[v] == 1) q[tail++] = v;
                    }
                }
            }
        }
        long total = 0;
        for (int i = 0; i < n; i++)
            if (!removed[i]) total += deg[i];
        System.out.println(total);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	flag := make([]int64, n)
	deg := make([]int, n)
	removed := make([]bool, n)
	for i := range flag {
		flag[i] = nextInt()
	}
	adj := make([][]int, n)
	for i := 0; i < n-1; i++ {
		a, b := int(nextInt()), int(nextInt())
		adj[a] = append(adj[a], b)
		adj[b] = append(adj[b], a)
		deg[a]++
		deg[b]++
	}
	// Phase 1: repeatedly strip leaves without data.
	q := []int{}
	for i := 0; i < n; i++ {
		if deg[i] <= 1 && flag[i] == 0 {
			q = append(q, i)
		}
	}
	for h := 0; h < len(q); h++ {
		u := q[h]
		if removed[u] {
			continue
		}
		removed[u] = true
		for _, v := range adj[u] {
			if !removed[v] {
				deg[v]--
				deg[u]--
				if deg[v] == 1 && flag[v] == 0 {
					q = append(q, v)
				}
			}
		}
	}
	// Phase 2: strip the two outermost leaf layers of what remains.
	q = q[:0]
	for i := 0; i < n; i++ {
		if !removed[i] && deg[i] == 1 {
			q = append(q, i)
		}
	}
	h := 0
	for round := 0; round < 2; round++ {
		end := len(q)
		for ; h < end; h++ {
			u := q[h]
			removed[u] = true
			for _, v := range adj[u] {
				if !removed[v] {
					deg[v]--
					deg[u]--
					if deg[v] == 1 {
						q = append(q, v)
					}
				}
			}
		}
	}
	total := 0
	for i := 0; i < n; i++ {
		if !removed[i] {
			total += deg[i]
		}
	}
	fmt.Println(total)
}
